import [IO] from "std/io.bpl";

# ❌ BAD: Unclear names
frame calc(a: int, b: int, c: int) ret int {
    return a * b + c;
}

# ✅ GOOD: Descriptive names
frame calculateOrderTotal(itemPrice: int, quantity: int, shippingCost: int) ret int {
    return itemPrice * quantity + shippingCost;
}

# ❌ BAD: Abbreviations
struct Usr {
    nm: string,
    addr: string,
}

# ✅ GOOD: Full words
struct User {
    name: string,
    address: string,
}

# ❌ BAD: Single letter variables (except loop indices)
frame bad(x: int, y: int) ret int {
    local z: int = x + y;
    return z;
}

# ✅ GOOD: Meaningful names
frame addScores(currentScore: int, bonus: int) ret int {
    local totalScore: int = currentScore + bonus;
    return totalScore;
}

frame main() ret int {
    IO.print("Good naming makes code self-documenting!\n");

    local price: int = 100;
    local qty: int = 3;
    local shipping: int = 10;

    IO.print("Order total: $");
    IO.printInt(calculateOrderTotal(price, qty, shipping));
    IO.print("\n");

    return 0;
}

import [IO] from "std/io.bpl";

enum Maybe<T> { Some(T), None }
enum Outcome<T, E> { Ok(T), Err(E) }

# ✅ Single Responsibility: Each function does ONE thing
frame isValidEmail(email: string) ret bool {
    # Simplified check - just look for @
    # In real code, use proper validation
    local len: int = 0;
    local hasAt: bool = false;
    local ptr: *char = cast<*char>(email);

    loop (*ptr != cast<char>(0)) {
        if (*ptr == '@') {
            hasAt = true;
        }
        len = len + 1;
        ptr = ptr + 1;
    }

    return hasAt && len >= 5;
}

# ✅ Return early on errors
frame processUser(name: string, email: string) ret Result<string, string> {
    # Check inputs first
    if (name == nullptr || name == "") {
        return Outcome.Err("Name is required");
    }

    if (isValidEmail(email) == false) {
        return Outcome.Err("Invalid email");
    }

    # Happy path continues after all checks
    return Outcome.Ok("User processed successfully");
}

# ✅ Keep functions short (under 30 lines)
# ✅ No more than 3-4 parameters

frame main() ret int {
    IO.print("=== Function Design ===\n\n");

    # Test valid input
    match (processUser("Alice", "alice@example.com")) {
        Outcome.Ok(msg) => {
            IO.print("Success: ");
            IO.print(msg);
            IO.print("\n");
        },
        Outcome.Err(err) => {
            IO.print("Error: ");
            IO.print(err);
            IO.print("\n");
        },
    }

    # Test invalid email
    match (processUser("Bob", "invalid")) {
        Outcome.Ok(msg) => {
            IO.print("Success: ");
            IO.print(msg);
        },
        Outcome.Err(err) => {
            IO.print("Error: ");
            IO.print(err);
        },
    }
    IO.print("\n");

    return 0;
}

import [IO] from "std/io.bpl";
extern malloc(size: int) ret *void;
extern free(ptr: *void);

enum Outcome<T, E> { Ok(T), Err(E) }

struct AllocationError {
    requested: int,
    message: string,
}

# ✅ Always handle potential failures
frame allocateBuffer(size: int) ret Result<*int, AllocationError> {
    if (size <= 0) {
        return Outcome.Err(AllocationError {
            requested: size,
            message: "Invalid size"
        });
    }

    local ptr: *int = cast<*int>(malloc(size * sizeof<int>()));

    if (ptr == nullptr) {
        return Outcome.Err(AllocationError {
            requested: size,
            message: "Allocation failed"
        });
    }

    return Outcome.Ok(ptr);
}

# ✅ Provide context in errors
struct OperationError {
    operation: string,
    details: string,
    code: int,
}

# ✅ Use defer for cleanup, even on errors
frame processData(size: int) ret Result<int, OperationError> {
    match (allocateBuffer(size)) {
        Outcome.Ok(buffer) => {
            defer { free(cast<*void>(buffer)); }

            # Process...
            loop (local i: int = 0; i < size; i = i + 1) {
                *(buffer + i) = i * 10;
            }

            # Calculate sum
            local sum: int = 0;
            loop (local i: int = 0; i < size; i = i + 1) {
                sum = sum + *(buffer + i);
            }

            return Outcome.Ok(sum);
        },
        Outcome.Err(e) => {
            return Outcome.Err(OperationError {
                operation: "processData",
                details: e.message,
                code: -1
            });
        },
    }
}

frame main() ret int {
    IO.print("=== Error Handling ===\n\n");

    # Success case
    match (processData(5)) {
        Outcome.Ok(sum) => {
            IO.print("Sum of 5 elements: ");
            IO.printInt(sum);
            IO.print("\n");
        },
        Outcome.Err(e) => {
            IO.print("Failed: ");
            IO.print(e.details);
            IO.print("\n");
        },
    }

    # Error case
    match (processData(-1)) {
        Outcome.Ok(sum) => {
            IO.print("Result: ");
            IO.printInt(sum);
            IO.print("\n");
        },
        Outcome.Err(e) => {
            IO.print("Failed: ");
            IO.print(e.details);
            IO.print("\n");
        },
    }

    return 0;
}

import [IO] from "std/io.bpl";
extern malloc(size: int) ret *void;
extern free(ptr: *void);

# ✅ Avoid unnecessary allocations

# ❌ BAD: Allocates in loop
frame badSum(n: int) ret int {
    local total: int = 0;
    loop (local i: int = 0; i < n; i = i + 1) {
        # Don't allocate inside loops!
        total = total + i;
    }
    return total;
}

# ✅ GOOD: Reuse allocations
struct Buffer {
    data: *int,
    size: int,
}

frame sumWithBuffer(buf: *Buffer, n: int) ret int {
    # Use pre-allocated buffer
    local total: int = 0;
    loop (local i: int = 0; i < n && i < buf.size; i = i + 1) {
        *(buf.data + i) = i;
        total = total + i;
    }
    return total;
}

# ✅ Prefer stack over heap when possible
frame stackExample() ret int {
    # Stack allocation - fast, automatic cleanup
    local arr: int[100];

    loop (local i: int = 0; i < 100; i = i + 1) {
        arr[i] = i * 2;
    }

    local sum: int = 0;
    loop (local i: int = 0; i < 100; i = i + 1) {
        sum = sum + arr[i];
    }
    return sum;
}

frame main() ret int {
    IO.print("=== Performance Tips ===\n\n");

    # Stack is fast
    local stackSum: int = stackExample();
    IO.print("Stack array sum: ");
    IO.printInt(stackSum);
    IO.print("\n");

    # Simple sum
    IO.print("Simple sum (0..99): ");
    IO.printInt(badSum(100));
    IO.print("\n");

    return 0;
}

