import [IO] from "std/io.bpl";

enum Maybe<T> { Some(T), None }

# Searches for target value in array.
# Returns Some(index) if found, None otherwise.
frame findIndex(arr: *int, length: int, target: int) ret Maybe<int> {
    loop (local index: int = 0; index < length; index = index + 1) {
        if (*(arr + index) == target) {
            return Maybe.Some(index);
        }
    }
    return Maybe.None;
}

frame main() ret int {
    local data: int[5] = [10, 20, 30, 40, 50];

    match (findIndex(&data[0], 5, 30)) {
        Maybe.Some(idx) => {
            IO.print("Found at index: ");
            IO.printInt(idx);
            IO.print("\n");
        },
        Maybe.None => {
            IO.print("Not found\n");
        },
    }

    return 0;
}
